package com.nequard.rewards;
import com.nequard.auth.OrganizationAccessService;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/rewards") public class NqdController{private final NqdRepository repo;private final OrganizationAccessService access;public NqdController(NqdRepository r,OrganizationAccessService a){repo=r;access=a;}@GetMapping("/users/{userId}/ledger")public List<NqdLedgerEntry> ledger(Authentication a,@PathVariable UUID userId){var u=access.currentUser(a);if(!access.isSuperAdmin(a)&&!u.getId().equals(userId))throw new SecurityException("TENANT_ACCESS_DENIED");return repo.findByUserIdOrderByCreatedAtDesc(userId);}@PostMapping("/ledger")public NqdLedgerEntry record(Authentication a,@RequestBody NqdLedgerEntry e){if(!access.isSuperAdmin(a)&&!access.currentUser(a).getId().equals(e.getUserId()))throw new SecurityException("TENANT_ACCESS_DENIED");return repo.save(e);}}